<script lang="ts">
  import {searchableSelect} from '#lib/client/searchable-select.ts';
 import{onMount}from'svelte';import{invalidateAll}from'$app/navigation';
 import type{Contour}from'@schubert/contracts';import{contourParts,contourBounds,sampleRing,parseMillimetres}from'@schubert/geometry';
 import{command}from'#lib/client/api.ts';import{uploadOriginal}from'#lib/client/uploads.ts';
 let{documents=[],planningProjectId,onapply,onclose}:{documents?:any[];planningProjectId:string;onapply:(contour:Contour)=>void;onclose:()=>void}=$props();
 let dialog:HTMLDialogElement,sourceVersion=$state(''),unit=$state(''),unitConfirmed=$state(false),tolerance=$state(''),report:any=$state(null),selectedPart=$state('all'),busy=$state(false),error=$state(''),notice=$state(''),uploadedVersion=$state('');
 const sources=$derived(documents.filter(d=>['image/svg+xml','application/dxf','image/vnd.dxf','application/x-dxf'].includes(d.mime_type)||/\.(svg|dxf)$/i.test(d.name??d.original_name??''))),parts=$derived(report?.contour?contourParts(report.contour):[]),bounds=$derived(report?.contour?contourBounds(report.contour):{minX:'0',maxY:'100',width:'100',height:'100'});
 const pad=$derived(Math.max(Number(bounds.width),Number(bounds.height))*.08+1),viewBox=$derived(`${Number(bounds.minX)-pad} ${-Number(bounds.maxY)-pad} ${Number(bounds.width)+pad*2} ${Number(bounds.height)+pad*2}`);
 onMount(()=>{dialog.showModal();return()=>dialog.close();});
 function reset(){report=null;unitConfirmed=false;error='';}
 async function upload(event:Event){const file=(event.currentTarget as HTMLInputElement).files?.[0];if(!file)return;if(!/\.(svg|dxf)$/i.test(file.name)||file.size>8*1024*1024){error='Ein vollständiges SVG-/ASCII-DXF-Original bis 8 MB auswählen.';return;}busy=true;error='';try{const result=await uploadOriginal(file,'planning_project',planningProjectId);uploadedVersion=result.current_version_id??'';notice='Original privat und versioniert abgelegt. Nach bestandener Dateiprüfung die Quellenliste aktualisieren; Quarantäne erteilt keine Geometrie- oder Nutzungsfreigabe.';await invalidateAll();}catch(e){error=(e as Error).message;}finally{busy=false;}}
 async function refreshSources(){busy=true;error='';try{await invalidateAll();if(uploadedVersion&&sources.some(d=>(d.version_id??d.id)===uploadedVersion)){sourceVersion=uploadedVersion;report=null;unitConfirmed=false;notice='Die abgelegte Originalversion ist für die Auswahl verfügbar. Einheit und Fehlergrenze anhand dieser Quelle festlegen.';}else notice='Quellenliste aktualisiert. Falls das Original noch nicht erscheint, ist seine Dateiprüfung noch offen; den Status im Dokumentenbereich prüfen.';}catch(problem){error=(problem as Error).message;}finally{busy=false;}}
 async function inspect(){busy=true;error='';report=null;try{const t=parseMillimetres(tolerance);if(!t)throw Error('Eine konkrete maximale Abweichung zwischen 0,02 und 5 mm angeben.');report=await command('planning.outline.inspect',undefined,{document_version_id:sourceVersion,source_unit:unit,unit_confirmed:unitConfirmed,tolerance_mm:t});selectedPart='all';}catch(e){error=(e as Error).message;}finally{busy=false;}}
 function path(part:Pick<Contour,'outer'|'holes'>){return[part.outer,...part.holes].map(r=>sampleRing(r,.02).map((p,i)=>`${i?'L':'M'}${p.xMm} ${-Number(p.yMm)}`).join(' ')+' Z').join(' ');}
 function apply(){error='';try{if(!report?.contour)return;let contour:Contour=structuredClone($state.snapshot(report.contour));if(selectedPart!=='all'){const index=Number(selectedPart);contour={...structuredClone(parts[index]),importProvenance:{...contour.importProvenance!,selectedPartIndex:index}};}onapply(contour);onclose();}catch(problem){error=(problem as Error).message;}}
</script>
<dialog bind:this={dialog} oncancel={onclose} onclose={onclose} aria-labelledby="outline-import-title"><header><div><p>ORIGINALKONTUR</p><h2 id="outline-import-title">SVG oder DXF übernehmen</h2></div><button type="button" aria-label="Schließen" onclick={onclose}>×</button></header>
 <div class="import-layout"><section class="source"><p class="intro">Geschlossene Geraden und Kreisbögen bleiben Geometrie. Bézier-, Ellipsen- und Splinekurven werden nur innerhalb Ihrer ausdrücklich gewählten Fehlergrenze angenähert. Die Übernahme bleibt fachlich ungeprüft.</p>
  <label>Neue Originaldatei ablegen<input type="file" accept=".svg,.dxf,image/svg+xml,application/dxf" onchange={upload} disabled={busy}/></label>
  <label>Private Originalversion<select use:searchableSelect={sourceVersion} bind:value={sourceVersion} onchange={reset} disabled={busy}><option value="">Geprüfte Originalversion auswählen</option>{#each sources as source}<option value={source.version_id??source.id}>{source.name??source.original_name} · {source.status==='available'?'verfügbar':source.status==='quarantine'?'Quarantäne':source.status??'Originalversion'}</option>{/each}</select></label>
  <button type="button" class="btn small" onclick={refreshSources} disabled={busy}>Quellenliste aktualisieren</button>
  <label>Tatsächliche Originaleinheit<select use:searchableSelect={unit} bind:value={unit} onchange={reset} disabled={busy}><option value="">Anhand der Quelle festlegen</option><option value="mm">Millimeter</option><option value="cm">Zentimeter</option><option value="m">Meter</option><option value="in">Zoll</option></select></label>
  <label class="check"><input type="checkbox" bind:checked={unitConfirmed} disabled={busy||!unit}/>Einheit anhand der Originalquelle geprüft. Es findet keine Maßableitung aus Bildschirmpixeln statt.</label>
  <label>Maximaler Importfehler (mm)<input bind:value={tolerance} inputmode="decimal" placeholder="Bewusst wählen, z. B. 0,05" oninput={()=>report=null} disabled={busy}/></label><p class="hint">0,02–5 mm einschließlich Koordinatenquantisierung auf 0,01 mm. Dies ist keine Fertigungstoleranz. DXF-Einheiten dürfen der Dateideklaration nicht widersprechen.</p>
  <button type="button" class="btn primary" onclick={inspect} disabled={busy||!sourceVersion||!unit||!unitConfirmed||!tolerance}>{busy?'Original wird geprüft …':'Konturen prüfen und anzeigen'}</button>
  {#if notice}<p class="notice" role="status">{notice}</p>{/if}{#if error}<p class="error" role="alert">{error}</p>{/if}
 </section><section class="result" aria-live="polite">{#if report}<div class="summary"><strong>{report.componentCount} {report.componentCount===1?'Bestandteil':'Bestandteile'} · {report.holeCount} {report.holeCount===1?'Loch':'Löcher'}</strong><span>{Number(report.boundsMm.width).toLocaleString('de-DE')} × {Number(report.boundsMm.height).toLocaleString('de-DE')} mm</span><p>{report.approximated?'Kontrollierte Kurvennäherung':'Analytische Geraden / Kreisbögen'} · Fehlergrenze {report.curveErrorBoundMm} mm</p></div>
   <svg class="preview" viewBox={viewBox} role="img" aria-label="Maßhaltige Vorschau der getrennten Außenkonturen und ihrer echten Löcher"><title>Konturvorschau in Millimetern</title>{#each parts as part,index}<path d={path(part)} fill={selectedPart==='all'||selectedPart===String(index)?'#abc0b0':'#e8ece7'} stroke="#315c4c" stroke-width={Math.max(Number(bounds.width),Number(bounds.height))/400+.01} fill-rule="evenodd"/>{/each}</svg>
   <label>Zu übernehmende Bestandteile<select use:searchableSelect={selectedPart} bind:value={selectedPart}><option value="all">Alle {parts.length} Bestandteile mit ihren Löchern</option>{#each parts as part,index}<option value={String(index)}>Bestandteil {index+1} · {part.holes.length} Löcher</option>{/each}</select></label>
   <details><summary>Quelle und Prüfergebnis</summary><p class="hash">SHA-256 {report.sourceContentHash}</p><p>{report.parserVersion} · {report.edgeCount} Kanten · {report.sourceUnit} → mm</p>{#each report.warnings as warning}<p class="hint">{warning}</p>{/each}</details>
  {:else}<div class="empty"><span>01 / ORIGINAL PRÜFEN</span><h3>Außenkonturen und Löcher getrennt sehen.</h3><p>Wählen Sie die tatsächliche Quelle und Maßeinheit. Erst danach erscheint die geometrische Vorschau.</p></div>{/if}</section></div>
 <footer><p>Kein Aufmaß, keine Hersteller- oder Fertigungsfreigabe durch den Import.</p><button type="button" class="btn" onclick={onclose}>Abbrechen</button><button type="button" class="btn primary" onclick={apply} disabled={!report||busy}>Als ungeprüfte Kontur übernehmen</button></footer>
</dialog>
<style>dialog{padding:0;border:1px solid var(--line);border-radius:10px;width:min(1050px,calc(100% - 32px));max-width:none;max-height:92dvh;background:var(--paper);color:var(--ink);box-shadow:0 24px 100px #16241c33}dialog::backdrop{background:#17251e66}header{display:flex;justify-content:space-between;align-items:center;padding:24px 28px;border-bottom:1px solid var(--line)}header p,.empty>span{font-size:11px;letter-spacing:.13em;color:var(--muted);margin:0 0 8px}h2{margin:0;font-size:23px}header button{font-size:28px;background:none;border:0;min-width:44px;min-height:44px;color:inherit}.import-layout{display:grid;grid-template-columns:minmax(290px,.85fr) minmax(320px,1.15fr);max-height:calc(92dvh - 178px);overflow:auto}.source,.result{padding:24px 28px}.source{border-right:1px solid var(--line);background:var(--paper)}.intro,.hint,.notice,.error{font-size:12px;line-height:1.65}.intro{margin:0 0 22px}.hint{color:var(--muted)}label{display:block;font-size:13px;font-weight:600;margin:18px 0}input,select{display:block;width:100%;font:inherit;font-size:14px;font-weight:400;box-sizing:border-box;border:1px solid var(--line);border-radius:4px;padding:10px 11px;margin-top:8px;min-height:44px;background:var(--paper);color:inherit}.check{display:flex;align-items:flex-start;gap:10px;font-weight:400;font-size:12px;line-height:1.6}.check input{width:18px;min-height:18px;margin:2px 0;flex:none}.source>.btn{width:100%;margin-top:12px}.summary strong,.summary span{display:block}.summary strong{font-size:18px}.summary span{font-size:14px;margin-top:8px}.summary p{font-size:12px;color:var(--muted)}.preview{display:block;width:100%;height:300px;background:#f4f4ef;border:1px solid #d9deda;border-radius:6px;margin-top:20px}.hash{overflow-wrap:anywhere;font-family:monospace;font-size:12px}.result details{font-size:12px;line-height:1.6;border-top:1px solid var(--line);padding-top:16px;margin-top:20px}.result summary{cursor:pointer;font-size:13px}.empty{height:100%;min-height:350px;display:flex;flex-direction:column;justify-content:center}.empty h3{font-size:26px;line-height:1.3;font-weight:500;margin:12px 0}.empty p{font-size:14px;line-height:1.7;color:var(--muted);max-width:340px}.error{padding:12px;background:var(--danger-wash);color:var(--danger)}.notice{padding:12px;background:var(--wash);color:var(--forest)}footer{display:flex;align-items:center;justify-content:flex-end;gap:12px;padding:18px 28px;border-top:1px solid var(--line)}footer p{font-size:12px;line-height:1.6;margin-right:auto;max-width:330px;color:var(--muted)}@media(max-width:760px){.import-layout{grid-template-columns:1fr}.source{border-right:0;border-bottom:1px solid var(--line)}.source,.result{padding:20px}.empty{min-height:180px}header{padding:20px}footer{flex-wrap:wrap;padding:16px 20px}footer p{max-width:none;width:100%}input,select,.btn{font-size:16px;min-height:48px}.preview{height:260px}}</style>
